<script setup>
/**
 * AiToolsDrawer — a right slide-over with Gemini study tools for the current
 * note: a study-tutor chat, a key-point summary, key terms, and a flashcard
 * preview. Everything is generated by AI (aiService); there is no rule-based
 * fallback, so when AI is disabled the drawer shows a single notice.
 */
import { ref, watch, onMounted, onUnmounted } from 'vue'
import { useI18n } from 'vue-i18n'
import { isAiConfigured, generateFlashcards } from '../../services/aiService.js'
import StudySummary from './StudySummary.vue'
import KeywordExtractor from './KeywordExtractor.vue'
import AiChat from './AiChat.vue'

const { t } = useI18n()

const props = defineProps({
  open: { type: Boolean, default: false },
  content: { type: String, default: '' },
  noteId: { type: String, default: '' }
})
const emit = defineEmits(['update:open'])

const flashcards = ref([])
const fcLoading = ref(false)

async function genPreview() {
  if (!isAiConfigured || !props.content) { flashcards.value = []; return }
  fcLoading.value = true
  try {
    flashcards.value = await generateFlashcards(props.content, { max: 6 })
  } catch {
    flashcards.value = []
  } finally {
    fcLoading.value = false
  }
}

// Generate the flashcard preview each time the drawer opens.
watch(() => props.open, (isOpen) => { if (isOpen) genPreview() })

function close() {
  emit('update:open', false)
}

// Close on Escape while open.
function onKey(e) {
  if (props.open && e.key === 'Escape') close()
}
onMounted(() => window.addEventListener('keydown', onKey))
onUnmounted(() => window.removeEventListener('keydown', onKey))
</script>

<template>
  <transition name="drawer">
    <div v-if="open" class="ai-drawer-wrap">
      <button class="ai-drawer-backdrop" :aria-label="t('common.cancel')" @click="close"></button>

      <aside class="ai-drawer" role="dialog" aria-modal="true">
        <header class="ai-drawer-head">
          <div>
            <div class="ai-drawer-title"><i class="bi bi-stars"></i>{{ t('editor.aiToolsTitle') }}</div>
            <div class="ai-drawer-sub">{{ t('editor.aiToolsSub') }}</div>
          </div>
          <button class="btn-icon-sq" :aria-label="t('common.cancel')" @click="close"><i class="bi bi-x-lg"></i></button>
        </header>

        <div class="ai-drawer-body">
          <div v-if="!isAiConfigured" class="panel tool-empty">{{ t('ai.disabled') }}</div>

          <template v-else>
            <AiChat :context="content" />
            <StudySummary :content="content" />
            <KeywordExtractor :content="content" />

            <!-- Flashcard preview -->
            <div class="panel">
              <div class="section-title"><i class="bi bi-card-text"></i>{{ t('editor.aiFlashcards') }}</div>
              <p v-if="fcLoading" class="tool-empty"><i class="bi bi-arrow-repeat spin"></i> {{ t('ai.generating') }}</p>
              <p v-else-if="!flashcards.length" class="tool-empty">{{ t('editor.aiFlashcardsEmpty') }}</p>
              <div v-for="(c, i) in flashcards" :key="i" class="ai-fc">
                <div class="ai-fc-q">{{ c.question }}</div>
                <div class="ai-fc-a">{{ c.answer }}</div>
              </div>
            </div>
          </template>
        </div>

        <footer class="ai-drawer-foot">
          <router-link :to="`/flashcards/${noteId}`" class="btn btn-brand ai-drawer-cta">
            <i class="bi bi-arrow-up-right"></i>{{ t('editor.openFullFlashcards') }}
          </router-link>
        </footer>
      </aside>
    </div>
  </transition>
</template>
